  'Monitoring and limits': 'Surveillance et limites',
  'Source checks use HTTP GET. Unchanged automatic runs skip the agent. An optional JSON pointer watches only that value and ignores object key order. Manual tests always run. Quiet hours defer successful Bot reports. Failures and approvals stay visible. Usage limits can overrun when reports arrive late.':
    "Les vérifications de source utilisent HTTP GET. Les exécutions automatiques inchangées ignorent l'agent. Un pointeur JSON facultatif surveille uniquement cette valeur et ignore l'ordre des clés d'objet. Les tests manuels sont toujours exécutés. Les heures calmes retardent la réussite des rapports de robots. Les échecs et les approbations restent visibles. Les limites d'utilisation peuvent être dépassées lorsque les rapports arrivent en retard.",
