    "Activer l'utilisation de l'ordinateur agent sur cet ordinateur",
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    "Accorde aux agents l’accès en écriture au bureau de cet ordinateur. Les agents en lecture seule sont exclus. L'utilisateur et les agents partagent l'état du bureau et de l'application.",
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    "Laissez Cua Driver vide pour le détecter sur le PATH de cet ordinateur ou dans son dossier d'installation standard. Les modifications s'appliquent aux tours des nouveaux agents.",
  '1. Install on this computer': '1. Installer sur cet ordinateur',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    "Exécutez le programme d'installation officiel sur l'hôte d'exécution, puis actualisez l'état. Il télécharge et installe CuaDriver ; aucun compte Cua n'est requis.",
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    "Les systèmes Linux minimaux ont besoin de libxi6 et at-spi2-core. GNOME a besoin de l'assistant WinRects fourni par Cua ; voir le guide d'installation.",
  'Install and set up Cua Driver': 'Installer et configurer le pilote Cua',
  'Detect / check Cua Driver': 'Détecter/vérifier le pilote Cua',
  '2. Permissions & desktop access': '2. Autorisations et accès au bureau',
  '3. Agent MCP, skills & hooks': '3. Agent MCP, compétences et crochets',
  '4. Computer History (optional preview)': "4. Historique de l'ordinateur (aperçu facultatif)",
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    "Accordez l'accessibilité macOS et l'enregistrement d'écran à CuaDriver et acceptez sa relance. Testez les applications des listes d’accès au bureau sans les modifier. Les contrôles du démon affectent les sessions actives d'utilisation de l'ordinateur.",
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    "Enregistrez le commutateur d'utilisation de l'ordinateur pour le dovo_cua MCP automatique sur les nouveaux tours inscriptibles. Aucune inscription manuelle au MCP n’est nécessaire. Installez le pack de compétences officiel en option ; les liens d'installation ont détecté des agents sur cet ordinateur.",
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    "Historique opt-in, crypté et contenant uniquement des métadonnées. L'activation peut redémarrer le démon. Désactiver conserve les données enregistrées ; la pause arrête temporairement l'enregistrement. Les versions non prises en charge signalent une erreur. Les données restent sur l'hôte d'exécution ; Afficher l'historique récent récupère jusqu'à 20 événements ici.",
