  'The PR and selected diff are added to an editable agent draft. Choose the model and send when ready.':
    "Le PR et le diff sélectionné sont ajoutés à un brouillon d'agent modifiable. Choisissez le modèle et envoyez-le lorsque vous êtes prêt.",
  'The PR source changed. Close and reopen this review action.':
    'La source des relations publiques a changé. Fermez et rouvrez cette action de révision.',
  'New commits are available. Keep your question and use the latest revision; selected lines will be cleared.':
    'De nouveaux commits sont disponibles. Conservez votre question et utilisez la dernière révision ; les lignes sélectionnées seront effacées.',
  'Use latest revision': 'Utiliser la dernière révision',
  'New review thread': 'Nouveau fil de discussion',
