  'Dovo Connect: {value0}': 'Dovo Connect : {value0}',
  'Pair again': 'Associez à nouveau',
  'Connection stages': 'Étapes de connexion',
  'Start your computer': 'Démarrez votre ordinateur',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    "Ouvrez Dovo sur votre ordinateur et gardez-le éveillé. Dans Paramètres → Appareils et environnement d'exécution, connectez-vous et activez Dovo Connect. Connectez-vous au même compte sur votre téléphone et choisissez Connecter. Aucun code de couplage, VPN ou IP locale n'est nécessaire pour accéder à Internet.",
  'Direct internet connection': 'Connexion Internet directe',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    "WebRTC + STUN connecte votre téléphone directement à l'ordinateur. Votre contenu est crypté de bout en bout. L'activation de Dovo Connect permet un relais chiffré de secours si un réseau bloque les connexions directes. Le relais transmet le trafic crypté ; il ne peut pas lire votre contenu.",
  'LAN / VPN connections': 'Connexions LAN/VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    "Associez LAN / VPN séparément pour préférer cette connexion lorsqu'elle est disponible. Copiez l'adresse Wi-Fi, Tailscale, NetBird ou HTTPS complète affichée sur votre ordinateur, y compris son port. localhost et 0.0.0.0 ne sont pas des adresses auxquelles votre téléphone peut se connecter.",
  'Check your network': 'Vérifiez votre réseau',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    "Utilisez le même Wi-Fi ou connectez les deux appareils à votre VPN. Pour les connexions Wi-Fi, autorisez Dovo à accéder à votre réseau local dans les paramètres de l'iPhone.",
