  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    "Exécute l'agent de chaque nouvelle conversation, ses commandes et ses terminaux dans un conteneur Docker ou Podman local. Seuls la copie de travail et l'identifiant de l'agent choisi sont montés. Les conversations en cours gardent leur réglage.",
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    "Sans accès réseau, l'agent ne peut pas joindre l'API de son modèle, sauf si cette API s'exécute dans la sandbox. Les installations de paquets et les requêtes web échouent aussi.",
