    "L'agent s'exécute sur cet ordinateur avec votre compte utilisateur.",
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    "L'agent, ses commandes et ses terminaux s'exécutent dans un conteneur. Seuls cette copie de travail et l'identifiant de l'agent sont montés.",
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Met en attente le nouveau travail exécuté sans votre message dès que son coût estimé atteint la limite. Cela concerne les suivis de Bot, les étapes de routine d’un Bot, les messages programmés et les agents enfants. Chaque fil ou Bot compte avec ses agents enfants. Une routine sans Bot commence un nouveau compte à chaque exécution. Définissez ses propres limites dans Surveillance et limites. Votre prochain message ou Continuer remet le compte à zéro. Les tours sans prix mettent aussi le travail en attente. Un tour en cours se termine toujours.',
